<script setup>
definePageMeta({ layout: 'auth' })
const { login } = useAuth()
const ready = useState('app-ready', () => false)
const { error } = useFeedback()
const email = ref(''); const password = ref(''); const busy = ref(false); const message = ref('')
async function submit() { busy.value=true;message.value='';try { await login(email.value,password.value) } catch(e) { message.value=error(e) } finally { busy.value=false } }
</script><template><div class="login-story"><NuxtLink to="/login" class="brand"><span class="brand-icon"><UiIcon name="leaf" :size="29" /></span><span>serene</span></NuxtLink><div><p class="eyebrow">A CALMER WAY TO WORK</p><h1>Exceptional care.<br />Effortless operations.</h1><p>Satu ruang untuk menghubungkan customer, tim, dan setiap momen pelayanan.</p><div class="story-decoration"><span /><UiIcon name="leaf" :size="96" /><span /></div></div><small>Serene Spa Management · Bali, Indonesia</small></div><div class="login-form-wrap"><form class="login-form" @submit.prevent="submit"><span class="overline">SELAMAT DATANG KEMBALI</span><h2>Masuk ke workspace</h2><p class="muted">Kelola hari Anda dengan lebih tenang.</p><label>Email<input v-model="email" :disabled="!ready" type="email" required autocomplete="username" placeholder="nama@spa.com" /></label><label>Password<input v-model="password" :disabled="!ready" type="password" required autocomplete="current-password" placeholder="Masukkan password Anda" /></label><p v-if="message" class="error-message" role="alert">{{ message }}</p><UiButton type="submit" :disabled="!ready" :loading="busy" class="w-full">Masuk <UiIcon name="arrow" :size="17" /></UiButton><p class="login-footnote"><UiIcon name="users" :size="15" />Akses diberikan oleh pengelola spa Anda.</p><NuxtLink to="/book" class="text-link">Ingin booking treatment? <UiIcon name="up" :size="15" /></NuxtLink></form></div></template>